<?php get_header(); ?><main id="content" class="container article-layout"><?php while(have_posts()): the_post(); ?><article class="post"><div class="breadcrumbs"><a href="<?php echo esc_url(home_url('/')); ?>">Trang chủ</a> / <?php the_category(', '); ?></div><?php $lesson_number=(int)get_post_meta(get_the_ID(),'_dttl_lesson_order',true); if($lesson_number): ?><div class="lesson-label">Bài <?php echo esc_html($lesson_number); ?> · <?php echo esc_html($lesson_number<=7?'Chặng nền tảng':($lesson_number<=13?'Thao tác & chi phí':($lesson_number<=19?'Hiểu doanh nghiệp':($lesson_number<=25?'Tích lũy dài hạn':'Phương pháp & rủi ro')))); ?> <a href="<?php echo esc_url(home_url('/lo-trinh-hoc/')); ?>">Xem lộ trình →</a></div><?php endif; ?><?php $app=get_post_meta(get_the_ID(),'_dttl_app_name',true); if($app): ?><div class="lesson-label"><?php echo esc_html($app); ?> · Bài <?php echo esc_html(get_post_meta(get_the_ID(),'_dttl_app_part',true)); ?>/3 <a href="<?php echo esc_url(home_url('/huong-dan-app-chung-khoan/')); ?>">Tra cứu app →</a></div><?php endif; ?><?php $extra=(int)get_post_meta(get_the_ID(),'_dttl_extra_order',true); if($extra): ?><div class="lesson-label">Đọc bổ sung · <?php echo esc_html(get_post_meta(get_the_ID(),'_dttl_extra_group',true)); ?> <a href="<?php echo esc_url(home_url('/thuat-ngu-chung-khoan/')); ?>">Tra thuật ngữ →</a></div><?php endif; ?><h1><?php the_title(); ?></h1><div class="post-meta">Đăng ngày <?php echo esc_html(get_the_date('d/m/Y')); ?> · Biên soạn: L0<?php if(get_the_modified_date('Ymd') !== get_the_date('Ymd')) echo ' · Cập nhật '.esc_html(get_the_modified_date('d/m/Y')); ?></div><div class="article-reader"><button type="button" id="reader-toggle" aria-label="Đọc bài viết" title="Đọc bài viết" aria-pressed="false"><svg class="reader-speaker" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M11 5 6 9H3v6h3l5 4V5Z"/><path d="M15 8a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14"/></svg><svg class="reader-pausing" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><rect x="6" y="4" width="4" height="16" rx="1"/><rect x="14" y="4" width="4" height="16" rx="1"/></svg></button><span id="reader-status" role="status" aria-live="polite" class="reader-sr"></span></div><?php if(has_post_thumbnail()) the_post_thumbnail('large',array('class'=>'featured-image')); ?><div class="entry-content"><?php the_content(); ?></div><aside class="post-note">Bài viết mang tính giáo dục và tham khảo; không phải khuyến nghị mua, bán chứng khoán.</aside><?php if($app) dttl_app_navigation(); elseif($extra) dttl_extra_navigation(); elseif (strpos(get_the_content(), 'dttl-topic-navigation') === false) dttl_lesson_navigation(); ?></article><?php endwhile; ?></main><?php get_footer(); ?>
